    project_root: Option<&Path>,
) -> Result<(PiSession, String), String> {
    let script = resolve_sidecar_script(app)?;
    let sidecar_dir = script
        .parent()
        .ok_or_else(|| "Cannot resolve pi-sidecar directory".to_string())?
        .to_path_buf();

    // B2.1: resolve the full ordered fallback chain (candidate 0 == primary).
    // `env_vars` stays candidate 0 for all existing env-var lines below (full
    // backward compatibility). The tail (candidates 1..N) is emitted as the
    // `DEVBOULE_PI_MODEL_CHAIN` env var (JSON); the sidecar ignores it until B2.2.
    let chain = resolve_coder_chain_for_sidecar(app, role);
    let mut env_vars = chain.first().cloned().unwrap_or_else(|| resolve_coder_env_for_sidecar(app, role));

    // --- macOS Seatbelt sandbox (decision #11) -------------------------------
    // Confine pi's edit/write/bash tools to the project directory. Default ON for
    // safety; toggle with DEVBOULE_PI_SANDBOX=false for debugging. On non-macOS
    // wrap/apply_rlimits are no-ops (passthrough), so we only wrap on macOS.
    // F1: prefer the explicit project_root over the sidecar-parent fallback.
    let effective_project_root = project_root
        .map(|p| p.to_path_buf())
        .unwrap_or_else(|| {
            sidecar_dir
                .parent()
                .map(|p| p.to_path_buf())
                .unwrap_or_else(|| sidecar_dir.clone())
        });

    // F3: resolve projects_dir and management_root for the sandbox policy and
    // the MCP config. These use the same resolution chain as claude/codex MCP
    // wiring.
    // Python: fail-soft if resolution fails (session works without Devboule tools).
    // Rust: fail-hard — soft-continue would leave a stale Python entry in `.pi/mcp.json`.
    let mcp_backend = crate::backend::mcp_backend::McpBackend::from_env();
    let mcp_paths = match crate::backend::pi_mcp_config::resolve_mcp_paths(app) {
        Ok(p) => Some(p),
        Err(e) if mcp_backend == crate::backend::mcp_backend::McpBackend::Rust => {
            return Err(format!(
                "devboule MCP paths could not be resolved (Rust backend requires a valid \
                 management root; refusing to spawn with a possibly-stale Python MCP entry): {e}"
            ));
        }
        Err(_) => None,
    };
    let (projects_dir, management_root) = mcp_paths
        .as_ref()
        .map(|(_, mgr, proj, _)| (proj.clone(), mgr.clone()))
        .unwrap_or_else(|| {
            // Fallback: use effective_project_root as both (sandbox stays
            // correct for the common case; MCP config is skipped).
            (effective_project_root.clone(), effective_project_root.clone())
        });
